CREATE FUNCTION tj_private.iqbuild_access(p_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
SELECT EXISTS(SELECT 1 FROM tj.organization_members m JOIN tj.organizations o ON o.id=m.organization_id WHERE m.organization_id=p_org AND m.user_id=tj_private.current_source_user_id() AND m.status='active' AND o.status='active' AND o.deleted_at IS NULL);$$;
REVOKE ALL ON FUNCTION tj_private.iqbuild_access(uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION tj_private.iqbuild_access(uuid) TO authenticated;
CREATE FUNCTION tj_private.iqbuild_parent_project(p_table text,p_id uuid) RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE result uuid;
BEGIN
 CASE p_table
 WHEN 'iqbuild_projects' THEN SELECT id INTO result FROM tj.iqbuild_projects WHERE id=p_id;
 WHEN 'iqbuild_buildings' THEN SELECT project_id INTO result FROM tj.iqbuild_buildings WHERE id=p_id;
 WHEN 'iqbuild_floors' THEN SELECT b.project_id INTO result FROM tj.iqbuild_floors f JOIN tj.iqbuild_buildings b ON b.id=f.building_id WHERE f.id=p_id;
 WHEN 'iqbuild_units' THEN SELECT b.project_id INTO result FROM tj.iqbuild_units u JOIN tj.iqbuild_floors f ON f.id=u.floor_id JOIN tj.iqbuild_buildings b ON b.id=f.building_id WHERE u.id=p_id;
 WHEN 'iqbuild_unit_appliances' THEN SELECT tj_private.iqbuild_parent_project('iqbuild_units',unit_id) INTO result FROM tj.iqbuild_unit_appliances WHERE id=p_id;
 WHEN 'iqbuild_packages' THEN SELECT project_id INTO result FROM tj.iqbuild_packages WHERE id=p_id;
 WHEN 'iqbuild_installations' THEN SELECT project_id INTO result FROM tj.iqbuild_installations WHERE id=p_id;
 WHEN 'iqbuild_deliveries' THEN SELECT project_id INTO result FROM tj.iqbuild_deliveries WHERE id=p_id;
 ELSE RAISE EXCEPTION 'unsupported_parent';END CASE;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION tj_private.iqbuild_parent_project(text,uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION tj_private.iqbuild_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE row_data jsonb:=to_jsonb(NEW);actor uuid:=tj_private.current_source_user_id();org uuid;location uuid;project uuid;parent_table text;parent_col text;ref record;ref_id uuid;ref_project uuid;ref_org uuid;ctx jsonb;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'mapped_identity_required' USING ERRCODE='42501';END IF;
 ctx:=tj_private.my_platform_context();
 IF TG_TABLE_NAME='iqbuild_projects' THEN org:=coalesce(NEW.organization_id,(ctx->>'organization_id')::uuid);project:=NEW.id;location:=CASE WHEN TG_OP='UPDATE' THEN OLD.location_id ELSE CASE WHEN org=(ctx->>'organization_id')::uuid THEN (ctx->>'location_id')::uuid END END;IF NEW.crm_deal_id IS NOT NULL THEN SELECT location_id INTO location FROM tj.crm_deals WHERE id=NEW.crm_deal_id;END IF;
 ELSIF TG_TABLE_NAME='iqbuild_milestone_templates' THEN org:=coalesce(NEW.organization_id,(ctx->>'organization_id')::uuid);
 ELSIF TG_TABLE_NAME='iqbuild_packages' AND row_data->>'project_id' IS NULL THEN org:=coalesce(NEW.organization_id,(ctx->>'organization_id')::uuid);location:=CASE WHEN TG_OP='UPDATE' THEN OLD.location_id ELSE CASE WHEN org=(ctx->>'organization_id')::uuid THEN (ctx->>'location_id')::uuid END END;
 ELSE
  parent_col:=TG_ARGV[0];parent_table:=TG_ARGV[1];
  ref_id:=(row_data->>parent_col)::uuid;
  IF ref_id IS NULL THEN RAISE EXCEPTION 'parent_required' USING ERRCODE='23514';END IF;
  project:=tj_private.iqbuild_parent_project(parent_table,ref_id);
  IF project IS NULL AND parent_table='iqbuild_packages' THEN SELECT organization_id,location_id INTO org,location FROM tj.iqbuild_packages WHERE id=ref_id;
  ELSE SELECT organization_id,location_id INTO org,location FROM tj.iqbuild_projects WHERE id=project;END IF;
  IF row_data->>'organization_id' IS NOT NULL AND (row_data->>'organization_id')::uuid IS DISTINCT FROM org THEN RAISE EXCEPTION 'organization_parent_mismatch' USING ERRCODE='23514';END IF;
 END IF;
 IF TG_TABLE_NAME<>'iqbuild_milestone_templates' AND NOT tj.aiq_store_allows(org,location) THEN RAISE EXCEPTION 'store_access_denied' USING ERRCODE='42501';END IF;
 IF NOT tj_private.iqbuild_access(org) THEN RAISE EXCEPTION 'organization_access_denied' USING ERRCODE='42501';END IF;
 IF TG_OP='UPDATE' AND OLD.location_id IS DISTINCT FROM location THEN RAISE EXCEPTION 'store_move_denied' USING ERRCODE='42501';END IF;
 IF row_data->>'location_id' IS NOT NULL AND (row_data->>'location_id')::uuid IS DISTINCT FROM location THEN RAISE EXCEPTION 'location_parent_mismatch' USING ERRCODE='23514';END IF;
 IF TG_OP='UPDATE' AND nullif(parent_col,'') IS NOT NULL AND to_jsonb(OLD)->>parent_col IS DISTINCT FROM row_data->>parent_col THEN RAISE EXCEPTION 'parent_move_denied' USING ERRCODE='42501';END IF;
 IF TG_OP='UPDATE' AND OLD.organization_id IS DISTINCT FROM org THEN RAISE EXCEPTION 'organization_move_denied' USING ERRCODE='42501';END IF;
 IF TG_TABLE_NAME='iqbuild_milestone_templates' AND NOT EXISTS(SELECT 1 FROM tj.organization_members WHERE organization_id=org AND user_id=actor AND status='active' AND role IN('owner','admin')) THEN RAISE EXCEPTION 'template_admin_required' USING ERRCODE='42501';END IF;
 FOR ref IN SELECT * FROM (VALUES ('target_building_id','iqbuild_buildings'),('building_id','iqbuild_buildings'),('floor_id','iqbuild_floors'),('unit_id','iqbuild_units'),('unit_appliance_id','iqbuild_unit_appliances'),('delivery_id','iqbuild_deliveries'),('replaces_appliance_id','iqbuild_unit_appliances'),('replacement_for','iqbuild_unit_appliances'),('package_id','iqbuild_packages'))v(col,tbl) LOOP
  IF row_data ? ref.col AND row_data->>ref.col IS NOT NULL AND ref.col IS DISTINCT FROM parent_col THEN
   ref_id:=(row_data->>ref.col)::uuid;ref_project:=tj_private.iqbuild_parent_project(ref.tbl,ref_id);
   EXECUTE format('SELECT organization_id FROM tj.%I WHERE id=$1',ref.tbl) INTO ref_org USING ref_id;
   IF ref_org IS DISTINCT FROM org OR (ref_project IS NOT NULL AND project IS NOT NULL AND ref_project<>project) THEN RAISE EXCEPTION 'cross_project_reference' USING ERRCODE='23514';END IF;
  END IF;
 END LOOP;
 IF row_data->>'milestone_template_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tj.iqbuild_milestone_templates WHERE id=(row_data->>'milestone_template_id')::uuid AND (organization_id IS NULL OR organization_id=org)) THEN RAISE EXCEPTION 'foreign_template' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME='iqbuild_projects' THEN
  IF TG_OP='INSERT' THEN IF NEW.created_by IS NOT NULL AND NEW.created_by<>actor THEN RAISE EXCEPTION 'actor_spoof' USING ERRCODE='42501';END IF;NEW.created_by:=actor;ELSIF NEW.created_by IS DISTINCT FROM OLD.created_by THEN RAISE EXCEPTION 'creator_immutable' USING ERRCODE='42501';END IF;
  IF NEW.crm_deal_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tj.crm_deals d WHERE d.id=NEW.crm_deal_id AND d.organization_id=org AND d.deleted_at IS NULL AND tj.aiq_scope_allows(org,d.owner_user_id) AND tj.aiq_store_allows(org,d.location_id)) THEN RAISE EXCEPTION 'crm_deal_access_denied' USING ERRCODE='42501';END IF;
  IF NEW.speciq_project_id IS NOT NULL AND NOT tj_private.speciq_project_store_allows(org,NEW.speciq_project_id) THEN RAISE EXCEPTION 'speciq_access_denied' USING ERRCODE='42501';END IF;
 END IF;
 IF TG_TABLE_NAME='iqbuild_packages' AND row_data->>'speciq_package_id' IS NOT NULL AND NOT tj_private.speciq_package_store_allows(org,(row_data->>'speciq_package_id')::uuid) THEN RAISE EXCEPTION 'speciq_package_access_denied' USING ERRCODE='42501';END IF;
 IF row_data ? 'assigned_buildings' OR row_data ? 'buildings_assigned' THEN
  FOR ref_id IN SELECT v::uuid FROM jsonb_array_elements_text(coalesce(nullif(row_data->'assigned_buildings','null'::jsonb),nullif(row_data->'buildings_assigned','null'::jsonb),'[]'::jsonb)) v LOOP
   IF tj_private.iqbuild_parent_project('iqbuild_buildings',ref_id) IS DISTINCT FROM project THEN RAISE EXCEPTION 'foreign_assigned_building' USING ERRCODE='23514';END IF;
  END LOOP;
 END IF;
 IF TG_TABLE_NAME='iqbuild_signoffs' THEN
  parent_table:=CASE NEW.entity_type WHEN 'unit' THEN 'iqbuild_units' WHEN 'project' THEN 'iqbuild_projects' ELSE NULL END;
  IF parent_table IS NULL OR tj_private.iqbuild_parent_project(parent_table,NEW.entity_id) IS DISTINCT FROM project THEN RAISE EXCEPTION 'foreign_signoff_entity' USING ERRCODE='23514';END IF;
 END IF;
 NEW:=jsonb_populate_record(NEW,jsonb_build_object('organization_id',org,'location_id',location));RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION tj_private.iqbuild_guard() FROM PUBLIC,anon,authenticated,service_role;
