CREATE POLICY iqbuild_insert ON tj.iqbuild_projects FOR INSERT TO authenticated WITH CHECK ((tj_private.iqbuild_access(organization_id) AND tj.aiq_store_allows(organization_id,location_id)));
CREATE POLICY iqbuild_update ON tj.iqbuild_projects FOR UPDATE TO authenticated USING ((tj_private.iqbuild_access(organization_id) AND tj.aiq_store_allows(organization_id,location_id))) WITH CHECK ((tj_private.iqbuild_access(organization_id) AND tj.aiq_store_allows(organization_id,location_id)));
