CREATE UNIQUE INDEX iqbuild_project_crm_once_idx ON tj.iqbuild_projects(organization_id,crm_deal_id) WHERE crm_deal_id IS NOT NULL;
CREATE FUNCTION tj_private.iqbuild_import(p_deal_id uuid,p_project jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=tj_private.current_source_user_id();ctx jsonb;org uuid;deal tj.crm_deals%ROWTYPE;proj uuid;sp uuid;record tj.iqbuild_projects%ROWTYPE;pkg tj.speciq_packages%ROWTYPE;new_pkg uuid;pc int:=0;ic int:=0;n int;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'mapped_identity_required' USING ERRCODE='42501';END IF;
 ctx:=tj_private.my_platform_context();org:=(ctx->>'organization_id')::uuid;
 IF NOT tj_private.iqbuild_access(org) THEN RAISE EXCEPTION 'organization_access_denied' USING ERRCODE='42501';END IF;
 SELECT * INTO deal FROM tj.crm_deals WHERE id=p_deal_id AND organization_id=org AND deleted_at IS NULL AND stage IN('Closed Won','Delivery Scheduled') AND tj.aiq_scope_allows(org,owner_user_id) AND tj.aiq_store_allows(org,location_id);
 IF NOT FOUND THEN RAISE EXCEPTION 'won_deal_access_denied' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('iqbuild_import:'||org::text||':'||p_deal_id::text,0));
 SELECT id INTO proj FROM tj.iqbuild_projects WHERE organization_id=org AND crm_deal_id=p_deal_id;
 IF FOUND THEN RETURN jsonb_build_object('project_id',proj,'already_imported',true,'packages',(SELECT count(*) FROM tj.iqbuild_packages WHERE project_id=proj),'items',(SELECT count(*) FROM tj.iqbuild_package_items i JOIN tj.iqbuild_packages p ON p.id=i.package_id WHERE p.project_id=proj));END IF;
 SELECT id INTO sp FROM tj.speciq_projects WHERE organization_id=org AND deal_id=p_deal_id AND deleted_at IS NULL AND tj_private.speciq_project_store_allows(org,id) ORDER BY created_at LIMIT 1;
 SELECT * INTO record FROM jsonb_populate_record(NULL::tj.iqbuild_projects,p_project);
 INSERT INTO tj.iqbuild_projects(organization_id,name,project_type,status,developer_name,developer_contact_email,developer_contact_phone,address_street,address_city,address_province,estimated_completion,budget_total,crm_deal_id,crm_contact_id,crm_company_id,speciq_project_id,imported_from_crm,created_by,import_summary)
 VALUES(org,coalesce(nullif(btrim(record.name),''),deal.title),coalesce(record.project_type,'condo'::public.iqbuild_project_type),coalesce(record.status,'planning'::public.iqbuild_project_status),record.developer_name,record.developer_contact_email,record.developer_contact_phone,record.address_street,record.address_city,record.address_province,record.estimated_completion,record.budget_total,deal.id,deal.contact_id,deal.company_id,sp,true,actor,jsonb_build_object('source_deal_updated_at',deal.updated_at,'source_deal_value',deal.value_amount,'source_currency',deal.value_currency,'received_at',clock_timestamp())) RETURNING id INTO proj;
 FOR pkg IN SELECT * FROM tj.speciq_packages WHERE organization_id=org AND deal_id=p_deal_id AND deleted_at IS NULL AND tj_private.speciq_package_store_allows(org,id) ORDER BY created_at LOOP
 INSERT INTO tj.iqbuild_packages(organization_id,project_id,name,description,is_builder_grade,unit_type,base_cost,speciq_package_id,source_snapshot,source_recorded_at) VALUES(org,proj,pkg.package_name,'Imported recorded SpecIQ package',true,pkg.unit_type,coalesce(pkg.total_final,pkg.total_negotiated,pkg.total_msrp),pkg.id,to_jsonb(pkg)-'share_token'-'share_url',pkg.updated_at) RETURNING id INTO new_pkg;pc:=pc+1;
 INSERT INTO tj.iqbuild_package_items(package_id,appliance_type,brand,model,product_id,unit_cost,sort_order,notes,speciq_product_id,aiq_product_id,category,finish,electrical_requirements,gas_requirements,water_requirements,ventilation_requirements,installation_type,msrp,negotiated_price,image_url,width_inches,height_inches,depth_inches,source_snapshot,source_recorded_at)
 SELECT new_pkg,coalesce(nullif(category,''),nullif(subcategory,''),'other'),brand,model_number,aiq_product_id,coalesce(negotiated_price,promo_price,msrp),sort_order,concat_ws(' — ',short_description,key_benefits),id,aiq_product_id,category,finish,electrical_requirements,gas_requirements,water_requirements,ventilation_requirements,installation_type,msrp,negotiated_price,image_url,width_inches,height_inches,depth_inches,to_jsonb(pr),updated_at FROM tj.speciq_package_products pr WHERE package_id=pkg.id AND organization_id=org;
 GET DIAGNOSTICS n=ROW_COUNT;ic:=ic+n;
 END LOOP;
 INSERT INTO tj.iqbuild_activity_log(project_id,entity_type,entity_id,action,new_value,description,performed_by) VALUES(proj,'project',proj,'imported_from_crm',deal.id::text,'Atomic import of recorded CRM and SpecIQ data',actor::text);
 RETURN jsonb_build_object('project_id',proj,'already_imported',false,'packages',pc,'items',ic);
END $$;
REVOKE ALL ON FUNCTION tj_private.iqbuild_import(uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION tj_private.iqbuild_import(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.tj_runtime_iqbuild_import(p_deal_id uuid,p_project jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$SELECT tj_private.iqbuild_import(p_deal_id,p_project);$$;
REVOKE ALL ON FUNCTION public.tj_runtime_iqbuild_import(uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.tj_runtime_iqbuild_import(uuid,jsonb) TO authenticated;
NOTIFY pgrst,'reload schema';
